import "server-only";
import { createAdminClient } from "@/lib/supabase/admin";

/**
 * `flight_departures` (111): the consolidated flights boxes ride. Delta Cargo,
 * JFK → Accra, every Wednesday and Friday, generated by `run_box_schedule()`.
 * No business logic here.
 */

export type DepartureStatus = "scheduled" | "closed" | "departed" | "cancelled";

export interface FlightDepartureRow {
  id: string;
  region_code: string;
  carrier: string;
  origin: string;
  destination: string;
  departs_on: string;
  departs_at: string;
  cutoff_at: string;
  status: DepartureStatus;
  awb: string | null;
}

const COLUMNS = "id, region_code, carrier, origin, destination, departs_on, departs_at, cutoff_at, status, awb";

/** The next departure per region that still takes boxes (cutoff ahead of `now`). */
export async function listNextDepartures(now: Date): Promise<Map<string, FlightDepartureRow>> {
  const { data, error } = await createAdminClient()
    .from("flight_departures")
    .select(COLUMNS)
    .eq("status", "scheduled")
    .gt("cutoff_at", now.toISOString())
    .order("departs_at", { ascending: true })
    .limit(50);
  if (error) throw new Error(`Failed to load departures: ${error.message}`);
  const next = new Map<string, FlightDepartureRow>();
  for (const row of (data ?? []) as FlightDepartureRow[]) if (!next.has(row.region_code)) next.set(row.region_code, row);
  return next;
}

/** Upcoming departures, soonest first (admin, /track). */
export async function listUpcomingDepartures(limit = 8): Promise<FlightDepartureRow[]> {
  const { data, error } = await createAdminClient()
    .from("flight_departures")
    .select(COLUMNS)
    .in("status", ["scheduled", "closed"])
    .gt("departs_at", new Date().toISOString())
    .order("departs_at", { ascending: true })
    .limit(limit);
  if (error) throw new Error(`Failed to load departures: ${error.message}`);
  return (data ?? []) as FlightDepartureRow[];
}

export async function listDeparturesByIds(ids: readonly string[]): Promise<Map<string, FlightDepartureRow>> {
  const wanted = [...new Set(ids.filter(Boolean))];
  if (wanted.length === 0) return new Map();
  const { data, error } = await createAdminClient().from("flight_departures").select(COLUMNS).in("id", wanted);
  if (error) throw new Error(`Failed to load departures: ${error.message}`);
  return new Map(((data ?? []) as FlightDepartureRow[]).map((d) => [d.id, d]));
}

/** Run the schedule job now: departures ahead, boxes closed at cutoff/capacity, plans rolled, empties archived. */
export async function runBoxSchedule(): Promise<Record<string, number>> {
  const { data, error } = await createAdminClient().rpc("run_box_schedule");
  if (error) throw new Error(`Box schedule failed: ${error.message}`);
  return (data ?? {}) as Record<string, number>;
}

/** 113: the departure a package leaving the hub today flies on: the first one dated today or later. */
export async function findShipDeparture(regionCode: string, now: Date): Promise<FlightDepartureRow | null> {
  const { data, error } = await createAdminClient()
    .from("flight_departures")
    .select(COLUMNS)
    .eq("region_code", regionCode)
    .in("status", ["scheduled", "closed"])
    .gte("departs_on", now.toISOString().slice(0, 10))
    .order("departs_at", { ascending: true })
    .limit(1)
    .maybeSingle();
  if (error) throw new Error(`Failed to load the departure: ${error.message}`);
  return (data as FlightDepartureRow | null) ?? null;
}

/** 113: record the air waybill on the departure the first time a package flies on it. */
export async function setDepartureAwbIfEmpty(id: string, awb: string): Promise<void> {
  const { error } = await createAdminClient().from("flight_departures").update({ awb, updated_at: new Date().toISOString() }).eq("id", id).is("awb", null);
  if (error) throw new Error(`Failed to record the air waybill: ${error.message}`);
}
